$ErrorActionPreference='Stop'
$js=@'
let sockets=[];
try{
const v=await(await fetch("http://127.0.0.1:17447/json/list")).json();
const ids=["251BEB4F668E7ADF5400D3821089D3F6","EF6A592F8DA7E5C66A6F6046DBB9B113"];
const out=[];
for(const id of ids){
 const tab=v.find(x=>x.id===id&&x.url.startsWith("https://www.avito.ru/krasnoyarsk/"));if(!tab){out.push({id,error:"NOT_FOUND"});continue}
 const ws=new WebSocket(tab.webSocketDebuggerUrl);sockets.push(ws);
 try{
 const answer=await Promise.race([new Promise((resolve,reject)=>{
 ws.addEventListener("open",()=>{const expression="(()=>{let s=document.body.innerText;let ix=s.indexOf('Описание');return {title:document.title,length:s.length,desc:ix>=0?s.slice(ix,ix+7200):s.slice(-7200)}})()";ws.send(JSON.stringify({id:123,method:"Runtime.evaluate",params:{expression,returnByValue:true}}))},{once:true});
 ws.addEventListener("message",e=>{let x=JSON.parse(e.data);if(x.id===123)resolve(x.result?.result?.value||{error:x.error?.code})});ws.addEventListener("error",reject,{once:true})
 }),new Promise((_,reject)=>setTimeout(()=>reject(Error("timeout")),7000))]);out.push({id,url:tab.url,data:answer})
 }catch(e){out.push({id,error:String(e).slice(0,100)})}ws.close()
}
console.log(JSON.stringify(out))
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,130)}))}
for(let w of sockets)try{w.close()}catch{};process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'avito-house-description-20261012.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
